CREATE TYPE "PurchaseOrderStatus" AS ENUM ('DRAFT','PENDING_APPROVAL','APPROVED','ORDERED','PARTIALLY_RECEIVED','RECEIVED','CANCELLED');
CREATE TYPE "InventoryReceiptType" AS ENUM ('PURCHASE_ORDER','AD_HOC');
CREATE TYPE "InventoryTransferStatus" AS ENUM ('DRAFT','POSTED','CANCELLED');
CREATE TYPE "InventoryEventType" AS ENUM ('VENDOR_CREATED','VENDOR_UPDATED','VENDOR_ARCHIVED','VENDOR_MAPPING_CHANGED','PO_CREATED','PO_SUBMITTED','PO_APPROVED','PO_ORDERED','PO_CANCELLED','RECEIPT_POSTED','PARTIAL_RECEIPT_POSTED','RECEIPT_COST_VARIANCE','TRANSFER_POSTED','REMAINING_QUANTITY_CLOSED');
ALTER TYPE "InventoryTransactionType" ADD VALUE 'PURCHASE';
CREATE TABLE "InventoryVendor" ("id" UUID PRIMARY KEY,"organizationId" TEXT NOT NULL,"name" TEXT NOT NULL,"normalizedName" TEXT NOT NULL,"contactName" TEXT,"email" TEXT,"phone" TEXT,"address" TEXT,"website" TEXT,"orderingWebsite" TEXT,"notes" TEXT,"defaultLeadTimeDays" INTEGER,"minimumOrder" DECIMAL(19,4),"freeShippingThreshold" DECIMAL(19,4),"archivedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE UNIQUE INDEX "InventoryVendor_organizationId_normalizedName_key" ON "InventoryVendor"("organizationId","normalizedName");
CREATE INDEX "InventoryVendor_organizationId_archivedAt_idx" ON "InventoryVendor"("organizationId","archivedAt");
CREATE TABLE "VendorItem" ("id" UUID PRIMARY KEY,"organizationId" TEXT NOT NULL,"vendorId" UUID NOT NULL,"itemId" UUID NOT NULL,"clinicLocationId" TEXT,"vendorSku" TEXT,"vendorBarcode" TEXT,"productUrl" TEXT,"purchaseUnit" TEXT NOT NULL,"stockUnit" TEXT NOT NULL,"purchaseToStock" DECIMAL(20,8) NOT NULL,"packageCost" DECIMAL(19,4),"minimumOrderQuantity" DECIMAL(20,6),"orderIncrement" DECIMAL(20,6),"isPreferred" BOOLEAN NOT NULL DEFAULT false,"isActive" BOOLEAN NOT NULL DEFAULT true,"lastOrderedAt" TIMESTAMP(3),"lastReceivedAt" TIMESTAMP(3),"archivedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "VendorItem_vendorId_fkey" FOREIGN KEY ("vendorId") REFERENCES "InventoryVendor"("id"),CONSTRAINT "VendorItem_itemId_fkey" FOREIGN KEY ("itemId") REFERENCES "CatalogItem"("id"));
CREATE UNIQUE INDEX "VendorItem_vendorId_itemId_clinicLocationId_purchaseUnit_key" ON "VendorItem"("vendorId","itemId","clinicLocationId","purchaseUnit");
CREATE INDEX "VendorItem_organizationId_itemId_isActive_idx" ON "VendorItem"("organizationId","itemId","isActive");
CREATE TABLE "PurchaseOrderSequence" ("organizationId" TEXT NOT NULL,"year" INTEGER NOT NULL,"nextValue" INTEGER NOT NULL DEFAULT 1,PRIMARY KEY ("organizationId","year"));
CREATE TABLE "PurchaseOrder" ("id" UUID PRIMARY KEY,"organizationId" TEXT NOT NULL,"clinicLocationId" TEXT NOT NULL,"vendorId" UUID NOT NULL,"number" TEXT NOT NULL,"status" "PurchaseOrderStatus" NOT NULL DEFAULT 'DRAFT',"orderDate" DATE,"expectedDate" DATE,"submittedAt" TIMESTAMP(3),"approvedAt" TIMESTAMP(3),"orderedAt" TIMESTAMP(3),"cancelledAt" TIMESTAMP(3),"receivedAt" TIMESTAMP(3),"notes" TEXT,"createdById" TEXT NOT NULL,"updatedById" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "PurchaseOrder_vendorId_fkey" FOREIGN KEY ("vendorId") REFERENCES "InventoryVendor"("id"));
CREATE UNIQUE INDEX "PurchaseOrder_organizationId_number_key" ON "PurchaseOrder"("organizationId","number"); CREATE INDEX "PurchaseOrder_organizationId_clinicLocationId_status_idx" ON "PurchaseOrder"("organizationId","clinicLocationId","status");
CREATE TABLE "PurchaseOrderLine" ("id" UUID PRIMARY KEY,"purchaseOrderId" UUID NOT NULL,"itemId" UUID NOT NULL,"vendorItemId" UUID,"itemNameSnapshot" TEXT NOT NULL,"skuSnapshot" TEXT,"purchaseUnitSnapshot" TEXT NOT NULL,"stockUnitSnapshot" TEXT NOT NULL,"conversionSnapshot" DECIMAL(20,8) NOT NULL,"orderedQuantity" DECIMAL(20,6) NOT NULL,"receivedQuantity" DECIMAL(20,6) NOT NULL DEFAULT 0,"unitCostSnapshot" DECIMAL(19,4),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "PurchaseOrderLine_purchaseOrderId_fkey" FOREIGN KEY ("purchaseOrderId") REFERENCES "PurchaseOrder"("id"),CONSTRAINT "PurchaseOrderLine_itemId_fkey" FOREIGN KEY ("itemId") REFERENCES "CatalogItem"("id"));
CREATE UNIQUE INDEX "PurchaseOrderLine_purchaseOrderId_itemId_purchaseUnitSnapsh_key" ON "PurchaseOrderLine"("purchaseOrderId","itemId","purchaseUnitSnapshot");
CREATE TABLE "InventoryReceipt" ("id" UUID PRIMARY KEY,"organizationId" TEXT NOT NULL,"clinicLocationId" TEXT NOT NULL,"vendorId" UUID NOT NULL,"purchaseOrderId" UUID,"type" "InventoryReceiptType" NOT NULL,"idempotencyKey" TEXT NOT NULL,"receivedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"reference" TEXT,"notes" TEXT,"postedById" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "InventoryReceipt_vendorId_fkey" FOREIGN KEY ("vendorId") REFERENCES "InventoryVendor"("id"),CONSTRAINT "InventoryReceipt_purchaseOrderId_fkey" FOREIGN KEY ("purchaseOrderId") REFERENCES "PurchaseOrder"("id") ON DELETE SET NULL);
CREATE UNIQUE INDEX "InventoryReceipt_organizationId_idempotencyKey_key" ON "InventoryReceipt"("organizationId","idempotencyKey"); CREATE INDEX "InventoryReceipt_organizationId_clinicLocationId_receivedAt_idx" ON "InventoryReceipt"("organizationId","clinicLocationId","receivedAt");
CREATE TABLE "InventoryReceiptLine" ("id" UUID PRIMARY KEY,"receiptId" UUID NOT NULL,"purchaseOrderLineId" UUID,"itemId" UUID NOT NULL,"stockLocationId" UUID NOT NULL,"lotId" UUID,"itemNameSnapshot" TEXT NOT NULL,"purchaseUnitSnapshot" TEXT NOT NULL,"stockUnitSnapshot" TEXT NOT NULL,"conversionSnapshot" DECIMAL(20,8) NOT NULL,"packageQuantity" DECIMAL(20,6) NOT NULL,"baseQuantity" DECIMAL(20,6) NOT NULL,"usableQuantity" DECIMAL(20,6) NOT NULL,"damagedQuantity" DECIMAL(20,6) NOT NULL DEFAULT 0,"rejectedQuantity" DECIMAL(20,6) NOT NULL DEFAULT 0,"quarantinedQuantity" DECIMAL(20,6) NOT NULL DEFAULT 0,"unitCostSnapshot" DECIMAL(19,4),"lotNumberSnapshot" TEXT,"expirationDateSnapshot" DATE,"transactionId" UUID,CONSTRAINT "InventoryReceiptLine_receiptId_fkey" FOREIGN KEY ("receiptId") REFERENCES "InventoryReceipt"("id"),CONSTRAINT "InventoryReceiptLine_purchaseOrderLineId_fkey" FOREIGN KEY ("purchaseOrderLineId") REFERENCES "PurchaseOrderLine"("id") ON DELETE SET NULL,CONSTRAINT "InventoryReceiptLine_itemId_fkey" FOREIGN KEY ("itemId") REFERENCES "CatalogItem"("id"));
CREATE TABLE "InventoryTransfer" ("id" UUID PRIMARY KEY,"organizationId" TEXT NOT NULL,"clinicLocationId" TEXT NOT NULL,"status" "InventoryTransferStatus" NOT NULL DEFAULT 'DRAFT',"idempotencyKey" TEXT NOT NULL,"reason" TEXT,"postedById" TEXT,"postedAt" TIMESTAMP(3),"createdById" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX "InventoryTransfer_organizationId_idempotencyKey_key" ON "InventoryTransfer"("organizationId","idempotencyKey"); CREATE INDEX "InventoryTransfer_organizationId_clinicLocationId_createdAt_idx" ON "InventoryTransfer"("organizationId","clinicLocationId","createdAt");
CREATE TABLE "InventoryTransferLine" ("id" UUID PRIMARY KEY,"transferId" UUID NOT NULL,"itemId" UUID NOT NULL,"sourceStockLocationId" UUID NOT NULL,"destinationStockLocationId" UUID NOT NULL,"sourceLotId" UUID,"destinationLotId" UUID,"quantity" DECIMAL(20,6) NOT NULL,"unitSnapshot" TEXT NOT NULL,"transactionGroupId" UUID NOT NULL,"outTransactionId" UUID,"inTransactionId" UUID,CONSTRAINT "InventoryTransferLine_transferId_fkey" FOREIGN KEY ("transferId") REFERENCES "InventoryTransfer"("id"),CONSTRAINT "InventoryTransferLine_itemId_fkey" FOREIGN KEY ("itemId") REFERENCES "CatalogItem"("id"));
CREATE TABLE "InventoryEvent" ("id" UUID PRIMARY KEY,"organizationId" TEXT NOT NULL,"clinicLocationId" TEXT,"type" "InventoryEventType" NOT NULL,"entityType" TEXT NOT NULL,"entityId" TEXT NOT NULL,"actorId" TEXT NOT NULL,"details" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "InventoryEvent_organizationId_clinicLocationId_createdAt_idx" ON "InventoryEvent"("organizationId","clinicLocationId","createdAt");
